// tb_mixed_workload_correctness.sv
//
// Phase 16: correctness check for the four mixed-heterogeneous-stream
// demo programs (sim/programs/scheduler/mixed_{dynamic,always_cpu,
// always_accel,oracle}_demo.s, generated by
// scheduler/runtime/gen_mixed_workload_demo.py). Same structure as
// Phase 15's sim/testbenches/tb_dynamic_scheduler_correctness.sv --
// all four programs run the identical 12-workload stream and write
// every block's real result to the same unified RAM location
// regardless of which engine produced it, so all four are checked
// against one expected-value table. Spot-checks (first/last element
// for arrays, full value for scalars) rather than every element:
// these are the exact same per-block body generators Phase 11/13/15
// already verified exhaustively element-by-element; what THIS
// testbench needs to catch is the multi-block generation/labeling
// machinery (the class of bug Phase 15 actually found), which
// spot-checks are sufficient for.
//
// Expected values computed in Python, not by hand:
//
//   python3 -c "
//   def vecadd(n): return [2*i+3 for i in range(n)]
//   def dot(n): return sum((i+1)*(i+2) for i in range(n))
//   def matmul(n):
//       A=[[i+j+1 for j in range(n)] for i in range(n)]
//       B=[[i+j+2 for j in range(n)] for i in range(n)]
//       return [sum(A[i][k]*B[k][j] for k in range(n))
//               for i in range(n) for j in range(n)]
//   print(vecadd(1), vecadd(2), dot(4), matmul(2))
//   print(vecadd(4), dot(8), vecadd(8))
//   print(matmul(4))
//   print(dot(16), vecadd(16)[0], vecadd(16)[-1])
//   print(dot(32), vecadd(32)[0], vecadd(32)[-1])
//   "

`timescale 1ns/1ps

module tb_mixed_workload_correctness;

  logic clk;
  logic rst_n = 0;

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  int errors = 0;

  task automatic check(string name, logic [31:0] actual, logic [31:0] expected);
    if (actual !== expected) begin
      $display("  [FAIL] %-28s expected=%0d actual=%0d", name, expected, actual);
      errors++;
    end else begin
      $display("  [PASS] %-28s = %0d", name, actual);
    end
  endtask

  task automatic check_sentinel(string name, logic [31:0] gpio_out);
    check({name, " sentinel"}, gpio_out, 32'hDEADBEEF);
  endtask

  `define SOC_PORTS(gpio_out_sig) \
    .clk(clk), .rst_n(rst_n), .gpio_in(32'b0), .gpio_out(gpio_out_sig), \
    .uart_tx_valid(), .uart_tx_byte(), \
    .dbg_if_pc(), .dbg_if_instr(), .dbg_id_pc(), .dbg_id_instr(), \
    .dbg_ex_pc(), .dbg_ex_instr(), .dbg_mem_instr(), .dbg_wb_instr(), \
    .dbg_reg_write(), .dbg_rd_addr(), .dbg_rd_data(), \
    .dbg_illegal(), .dbg_stall(), .dbg_flush(), \
    .perf_cycle_count(), .perf_instr_retired_count(), .perf_stall_count(), \
    .perf_branch_count(), .perf_branch_taken_count(), .perf_load_use_stall_count(), \
    .perf_forwarding_event_count(), .perf_flush_count()

  logic [31:0] dyn_gpio, cpu_gpio, accel_gpio, oracle_gpio;

  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/mixed_dynamic_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_dyn (`SOC_PORTS(dyn_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/mixed_always_cpu_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_cpu (`SOC_PORTS(cpu_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/mixed_always_accel_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_accel (`SOC_PORTS(accel_gpio));
  riscv_soc #(.IMEM_INIT_FILE("sim/programs/scheduler/mixed_oracle_demo.hex"), .RAM_DEPTH_WORDS(4096))
    dut_oracle (`SOC_PORTS(oracle_gpio));

  localparam int MAX_CYCLES = 40000; // mixed_always_cpu_demo (matmul N=4 +
                                      // dot N=32 all on CPU) is the costliest;
                                      // kept generous rather than tuned tight.

  // block i's unified output base, in RAM WORD indices: 0xC00 + i*0x40
  // (0x3000 + i*0x100 bytes, /4).
  function automatic int unsigned wbase(int i);
    return 32'd3072 + i * 32'd64; // 0x0C00 + i*0x40
  endfunction

  initial begin
    $display("=== Phase 16 mixed-heterogeneous-stream correctness check ===");

    rst_n = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n = 1;

    repeat (MAX_CYCLES) @(posedge clk);
    #1;

    check_sentinel("mixed_dynamic_demo", dyn_gpio);
    check_sentinel("mixed_always_cpu_demo", cpu_gpio);
    check_sentinel("mixed_always_accel_demo", accel_gpio);
    check_sentinel("mixed_oracle_demo", oracle_gpio);

    // block0: vecadd N=1 -> [3]
    $display("");
    $display("--- block0: vecadd N=1 ---");
    check("dyn    ", dut_dyn.ram_inst.mem[wbase(0)+0], 32'd3);
    check("cpu    ", dut_cpu.ram_inst.mem[wbase(0)+0], 32'd3);
    check("accel  ", dut_accel.ram_inst.mem[wbase(0)+0], 32'd3);
    check("oracle ", dut_oracle.ram_inst.mem[wbase(0)+0], 32'd3);

    // block1: vecadd N=2 -> [3,5]
    $display("");
    $display("--- block1: vecadd N=2 ---");
    check("dyn   [0]", dut_dyn.ram_inst.mem[wbase(1)+0], 32'd3);
    check("dyn   [1]", dut_dyn.ram_inst.mem[wbase(1)+1], 32'd5);
    check("cpu   [0]", dut_cpu.ram_inst.mem[wbase(1)+0], 32'd3);
    check("cpu   [1]", dut_cpu.ram_inst.mem[wbase(1)+1], 32'd5);
    check("accel [0]", dut_accel.ram_inst.mem[wbase(1)+0], 32'd3);
    check("accel [1]", dut_accel.ram_inst.mem[wbase(1)+1], 32'd5);
    check("oracle[0]", dut_oracle.ram_inst.mem[wbase(1)+0], 32'd3);
    check("oracle[1]", dut_oracle.ram_inst.mem[wbase(1)+1], 32'd5);

    // block2: dot N=4 -> 40
    $display("");
    $display("--- block2: dot N=4 ---");
    check("dyn    ", dut_dyn.ram_inst.mem[wbase(2)+0], 32'd40);
    check("cpu    ", dut_cpu.ram_inst.mem[wbase(2)+0], 32'd40);
    check("accel  ", dut_accel.ram_inst.mem[wbase(2)+0], 32'd40);
    check("oracle ", dut_oracle.ram_inst.mem[wbase(2)+0], 32'd40);

    // block3: matmul N=2 -> [8,11,13,18]
    $display("");
    $display("--- block3: matmul N=2 ---");
    check("dyn   [0]", dut_dyn.ram_inst.mem[wbase(3)+0], 32'd8);
    check("dyn   [3]", dut_dyn.ram_inst.mem[wbase(3)+3], 32'd18);
    check("cpu   [0]", dut_cpu.ram_inst.mem[wbase(3)+0], 32'd8);
    check("cpu   [3]", dut_cpu.ram_inst.mem[wbase(3)+3], 32'd18);
    check("accel [0]", dut_accel.ram_inst.mem[wbase(3)+0], 32'd8);
    check("accel [3]", dut_accel.ram_inst.mem[wbase(3)+3], 32'd18);
    check("oracle[0]", dut_oracle.ram_inst.mem[wbase(3)+0], 32'd8);
    check("oracle[3]", dut_oracle.ram_inst.mem[wbase(3)+3], 32'd18);

    // block4: vecadd N=4 -> [3,5,7,9]
    $display("");
    $display("--- block4: vecadd N=4 ---");
    check("dyn   [0]", dut_dyn.ram_inst.mem[wbase(4)+0], 32'd3);
    check("dyn   [3]", dut_dyn.ram_inst.mem[wbase(4)+3], 32'd9);
    check("cpu   [0]", dut_cpu.ram_inst.mem[wbase(4)+0], 32'd3);
    check("cpu   [3]", dut_cpu.ram_inst.mem[wbase(4)+3], 32'd9);
    check("accel [0]", dut_accel.ram_inst.mem[wbase(4)+0], 32'd3);
    check("accel [3]", dut_accel.ram_inst.mem[wbase(4)+3], 32'd9);
    check("oracle[0]", dut_oracle.ram_inst.mem[wbase(4)+0], 32'd3);
    check("oracle[3]", dut_oracle.ram_inst.mem[wbase(4)+3], 32'd9);

    // block5: dot N=8 -> 240
    $display("");
    $display("--- block5: dot N=8 ---");
    check("dyn    ", dut_dyn.ram_inst.mem[wbase(5)+0], 32'd240);
    check("cpu    ", dut_cpu.ram_inst.mem[wbase(5)+0], 32'd240);
    check("accel  ", dut_accel.ram_inst.mem[wbase(5)+0], 32'd240);
    check("oracle ", dut_oracle.ram_inst.mem[wbase(5)+0], 32'd240);

    // block6: vecadd N=8 -> [3,5,7,9,11,13,15,17]
    $display("");
    $display("--- block6: vecadd N=8 ---");
    check("dyn   [0]", dut_dyn.ram_inst.mem[wbase(6)+0], 32'd3);
    check("dyn   [7]", dut_dyn.ram_inst.mem[wbase(6)+7], 32'd17);
    check("cpu   [0]", dut_cpu.ram_inst.mem[wbase(6)+0], 32'd3);
    check("cpu   [7]", dut_cpu.ram_inst.mem[wbase(6)+7], 32'd17);
    check("accel [0]", dut_accel.ram_inst.mem[wbase(6)+0], 32'd3);
    check("accel [7]", dut_accel.ram_inst.mem[wbase(6)+7], 32'd17);
    check("oracle[0]", dut_oracle.ram_inst.mem[wbase(6)+0], 32'd3);
    check("oracle[7]", dut_oracle.ram_inst.mem[wbase(6)+7], 32'd17);

    // block7: matmul N=4 -> C[0]=40, C[15]=148
    $display("");
    $display("--- block7: matmul N=4 ---");
    check("dyn   [0]",  dut_dyn.ram_inst.mem[wbase(7)+0],  32'd40);
    check("dyn   [15]", dut_dyn.ram_inst.mem[wbase(7)+15], 32'd148);
    check("cpu   [0]",  dut_cpu.ram_inst.mem[wbase(7)+0],  32'd40);
    check("cpu   [15]", dut_cpu.ram_inst.mem[wbase(7)+15], 32'd148);
    check("accel [0]",  dut_accel.ram_inst.mem[wbase(7)+0],  32'd40);
    check("accel [15]", dut_accel.ram_inst.mem[wbase(7)+15], 32'd148);
    check("oracle[0]",  dut_oracle.ram_inst.mem[wbase(7)+0],  32'd40);
    check("oracle[15]", dut_oracle.ram_inst.mem[wbase(7)+15], 32'd148);

    // block8: dot N=16 -> 1632
    $display("");
    $display("--- block8: dot N=16 ---");
    check("dyn    ", dut_dyn.ram_inst.mem[wbase(8)+0], 32'd1632);
    check("cpu    ", dut_cpu.ram_inst.mem[wbase(8)+0], 32'd1632);
    check("accel  ", dut_accel.ram_inst.mem[wbase(8)+0], 32'd1632);
    check("oracle ", dut_oracle.ram_inst.mem[wbase(8)+0], 32'd1632);

    // block9: vecadd N=16 -> first 3, last(15) 33
    $display("");
    $display("--- block9: vecadd N=16 ---");
    check("dyn   [0]",  dut_dyn.ram_inst.mem[wbase(9)+0],  32'd3);
    check("dyn   [15]", dut_dyn.ram_inst.mem[wbase(9)+15], 32'd33);
    check("cpu   [0]",  dut_cpu.ram_inst.mem[wbase(9)+0],  32'd3);
    check("cpu   [15]", dut_cpu.ram_inst.mem[wbase(9)+15], 32'd33);
    check("accel [0]",  dut_accel.ram_inst.mem[wbase(9)+0],  32'd3);
    check("accel [15]", dut_accel.ram_inst.mem[wbase(9)+15], 32'd33);
    check("oracle[0]",  dut_oracle.ram_inst.mem[wbase(9)+0],  32'd3);
    check("oracle[15]", dut_oracle.ram_inst.mem[wbase(9)+15], 32'd33);

    // block10: dot N=32 -> 11968
    $display("");
    $display("--- block10: dot N=32 ---");
    check("dyn    ", dut_dyn.ram_inst.mem[wbase(10)+0], 32'd11968);
    check("cpu    ", dut_cpu.ram_inst.mem[wbase(10)+0], 32'd11968);
    check("accel  ", dut_accel.ram_inst.mem[wbase(10)+0], 32'd11968);
    check("oracle ", dut_oracle.ram_inst.mem[wbase(10)+0], 32'd11968);

    // block11: vecadd N=32 -> first 3, last(31) 65
    $display("");
    $display("--- block11: vecadd N=32 ---");
    check("dyn   [0]",  dut_dyn.ram_inst.mem[wbase(11)+0],  32'd3);
    check("dyn   [31]", dut_dyn.ram_inst.mem[wbase(11)+31], 32'd65);
    check("cpu   [0]",  dut_cpu.ram_inst.mem[wbase(11)+0],  32'd3);
    check("cpu   [31]", dut_cpu.ram_inst.mem[wbase(11)+31], 32'd65);
    check("accel [0]",  dut_accel.ram_inst.mem[wbase(11)+0],  32'd3);
    check("accel [31]", dut_accel.ram_inst.mem[wbase(11)+31], 32'd65);
    check("oracle[0]",  dut_oracle.ram_inst.mem[wbase(11)+0],  32'd3);
    check("oracle[31]", dut_oracle.ram_inst.mem[wbase(11)+31], 32'd65);

    $display("");
    if (errors == 0) begin
      $display("RESULT: ALL CHECKS PASSED");
    end else begin
      $display("RESULT: %0d CHECK(S) FAILED", errors);
    end
    $finish;
  end

endmodule
